import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
  JxButton,
} from '@jinx-ui/react';

type SpendStatus = 'active' | 'paused' | 'over';

interface SpendProject {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: SpendStatus;
}

const STATUS_FILTERS: Array<{ value: SpendStatus; label: string }> = [
  { value: 'active', label: 'Активные' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over', label: 'Превышение' },
];

const STATUS_META: Record<
  SpendStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
};

const PAGE_SIZE = 5;

const PROJECTS: SpendProject[] = [
  { id: 'p1', name: 'Контекстный движок', used: 180, quota: 400, status: 'active' },
  { id: 'p2', name: 'Аналитика обращений', used: 96, quota: 120, status: 'active' },
  { id: 'p3', name: 'Миграция биллинга', used: 55, quota: 300, status: 'paused' },
  { id: 'p4', name: 'Поиск по документам', used: 470, quota: 400, status: 'over' },
  { id: 'p5', name: 'Мобильный клиент', used: 210, quota: 500, status: 'active' },
  { id: 'p6', name: 'Импорт из внешних CRM', used: 20, quota: 250, status: 'paused' },
  { id: 'p7', name: 'Рассылки и уведомления', used: 330, quota: 350, status: 'active' },
  { id: 'p8', name: 'Экспорт отчётов за произвольный период', used: 610, quota: 500, status: 'over' },
  { id: 'p9', name: 'Витрина метрик', used: 140, quota: 600, status: 'active' },
  { id: 'p10', name: 'Архив старых проектов', used: 12, quota: 100, status: 'paused' },
  { id: 'p11', name: 'Интеграция с почтой', used: 275, quota: 300, status: 'active' },
  { id: 'p12', name: 'Песочница экспериментов', used: 88, quota: 200, status: 'paused' },
];

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<SpendStatus[]>(['active', 'over']);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () =>
      statuses.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = visible.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const toggleStatus = (status: SpendStatus) => {
    setStatuses((current) =>
      current.includes(status)
        ? current.filter((item) => item !== status)
        : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses([]);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_FILTERS.map((filter) => {
          const active = statuses.includes(filter.value);
          return (
            <JxChip
              key={filter.value}
              active={active}
              removable={active}
              onRemove={() => toggleStatus(filter.value)}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => toggleStatus(filter.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(filter.value);
                }
              }}
            >
              {filter.label}
            </JxChip>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Снимите часть статусов, чтобы снова увидеть проекты и их расход квоты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {rows.map((project) => {
              const meta = STATUS_META[project.status];
              const percent = Math.round((project.used / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <span
                    style={{
                      flex: '1 1 auto',
                      minWidth: 0,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                    title={project.name}
                  >
                    {project.name}
                  </span>
                  <JxProgressCircle
                    value={Math.min(percent, 100)}
                    showValue
                    aria-label={`Квота ${project.name}: ${percent}%`}
                  />
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          )}
        </>
      )}
    </section>
  );
}

